INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 0, 24001, 10040, 102601, "リン", "あたしだって\nやるときはやるよ！", 1, 1, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 1, 24002, 10040, 102601, "リン", "ふぅ…\nこれであたしの仕事は\n終わりだね", 1, 1, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 2, 24003, 10040, 102601, "リン", "終わった終わった\n一人でもなんとか\nなるもんだね", 1, 1, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 3, 24004, 10040, 102601, "リン", "やったね！\nこれでようやく\nサボれるよ…", 2, 2, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 4, 24005, 10040, 102601, "リン", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 1, 1, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 5, 24006, 10040, 102601, "リン", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 2, 2, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 6, 24007, 10040, 102601, "リン", "あたしも意外と\nやるもんでしょ？", 2, 2, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 7, 24008, 10040, 102601, "リン", "疲れた…\nねずみの逃げ足\n速すぎるよ…", 4, 4, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 8, 24009, 10040, 102601, "リン", "このままじゃ\nまっひ～に\n叱られちゃうよ", 4, 4, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 9, 24010, 10040, 102601, "リン", "まじめに\nやったんだけどな…\n悔しいな～", 4, 4, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 10, 24011, 10040, 102601, "リン", "やられた…\nねずみって意外と\nてごわいね", 4, 4, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 11, 24012, 10040, 102601, "リン", "おのれ～\nあたしのチーズを\n盗みやがって～！", 4, 4, "2020/04/30 12:00:00", 0.0, 24, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, "2030/12/17 14:59:59", 12, 24013, 10040, 102601, "リン", "疲れた…\nけど、次こそは\n守り抜くよ…", 1, 4, "2020/04/30 12:00:00", 1.81, 24, 0.0);
